{"file_path":"src/count.js","content":"/** The instant-runoff count. */

/**
 * Run the count. Returns { rounds, winner } where each round is
 * { counts: Map<name, votes>, order: name[], exhausted, eliminated }.
 */
export function runElection (candidates, ballots) {
  const continuing = new Set(candidates)
  const rounds = []
  let winner = null

  while (true) {
    const counts = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) counts.set(name, 0)
    }
    let exhausted = 0
    for (const ballot of ballots) {
      const pick = ballot.names.find((name) => continuing.has(name))
      if (pick === undefined) exhausted += ballot.count
      else counts.set(pick, counts.get(pick) + ballot.count)
    }
    let active = 0
    for (const votes of counts.values()) active += votes

    const order = [...counts.keys()].sort((a, b) => {
      const d = counts.get(b) - counts.get(a)
      return d !== 0 ? d : (a < b ? -1 : a > b ? 1 : 0)
    })
    const round = { counts, order, exhausted, eliminated: null }
    rounds.push(round)

    if (active === 0) break

    let leader = null
    for (const [name, votes] of counts) {
      if (votes * 2 > active) leader = name
    }
    if (leader !== null) {
      winner = leader
      break
    }

    const loser = chooseLoser(counts, rounds)
    round.eliminated = loser
    continuing.delete(loser)
  }

  return { rounds, winner }
}

function chooseLoser (counts, rounds) {
  let least = Infinity
  for (const votes of counts.values()) least = Math.min(least, votes)
  let tied = [...counts.keys()].filter((name) => counts.get(name) === least)

  while (tied.length > 1) {
    let split = null
    for (const round of rounds) {
      const values = tied.map((name) => round.counts.get(name))
      if (values.some((v) => v !== values[0])) {
        split = round
        break
      }
    }
    if (split === null) break
    let min = Infinity
    for (const name of tied) min = Math.min(min, split.counts.get(name))
    tied = tied.filter((name) => split.counts.get(name) === min)
  }

  if (tied.length === 1) return tied[0]
  return tied.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))[tied.length - 1]
}
"}

