{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parse.js'
import { runElection } from './count.js'

function die (message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin () {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main (argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'rounds' && mode !== 'tally')) {
    die('usage: cli.js rounds|tally')
  }

  let election
  try {
    election = parseElection(readStdin())
  } catch (err) {
    if (err instanceof ParseError) die(err.message)
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)
  const out = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const parts = round.order.map((name) => `${name}=${round.counts.get(name)}`)
      parts.push(`exhausted=${round.exhausted}`)
      out.push(`round ${index + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) out.push(`eliminated ${round.eliminated}`)
    })
  } else {
    out.push(`rounds ${rounds.length}`)
  }
  out.push(winner === null ? 'no winner' : `winner ${winner}`)
  process.stdout.write(out.join('\n') + '\n')
}

main(process.argv.slice(2))
"}

